/**
 * Ground-truth assertions over a real ingest.
 *
 * This is tier one of the eval suite and the half that matters most, because
 * it needs no model and no API key: it verifies that the *data* the agent
 * reasons over is correct. If these fail, no amount of prompt work will make
 * the agent right.
 *
 * It runs a genuine scan against the seeded mock account and checks the result
 * against the answer key in `topology.ts` - which was written by hand from the
 * topology, not generated by the code under test, so an analyser bug cannot
 * grade itself as correct.
 *
 * Requires the compose stack. Skipped automatically when moto is unreachable,
 * so a unit-test run on a laptop with nothing running still passes.
 */

import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { GROUND_TRUTH, seed } from "@daveio/mock-aws";
import { INTERNET_ARN } from "@daveio/shared";

import { runScan } from "../scan/runner.js";
import type { Relationship, Resource } from "@daveio/shared";

let resources: Resource[] = [];
let relationships: Relationship[] = [];
let available = false;

const byName = (name: string) => resources.find((r) => r.name === name);
const namesWhere = (predicate: (r: Resource) => boolean) =>
  resources
    .filter(predicate)
    .map((r) => r.name)
    .sort();

beforeAll(async () => {
  try {
    const endpoint = process.env["AWS_ENDPOINT_URL"] ?? "http://localhost:5000";
    const res = await fetch(`${endpoint}/moto-api/`).catch(() => null);
    if (!res?.ok) return;

    await seed();
    const result = await runScan({ scanId: "eval" });
    resources = result.resources;
    relationships = result.relationships;
    available = true;
  } catch (err) {
    console.warn("Ground-truth suite skipped:", err instanceof Error ? err.message : err);
  }
}, 180_000);

afterAll(() => {
  if (!available) {
    console.warn(
      "\n  Ground-truth suite did not run: moto was unreachable.\n" +
        "  Start it with `docker compose up -d` to exercise these.\n",
    );
  }
});

describe.runIf(!process.env["SKIP_INTEGRATION"])("ingest ground truth", () => {
  it("scans every service without a fatal error", () => {
    if (!available) return;
    expect(resources.length).toBeGreaterThan(50);
    expect(relationships.length).toBeGreaterThan(50);
  });

  describe("which buckets are public", () => {
    it("finds exactly the buckets that are genuinely public", () => {
      if (!available) return;
      const found = namesWhere((r) => r.kind === "S3Bucket" && r.derived.isPublic === true);
      expect(found).toEqual([...GROUND_TRUTH.publicBuckets].sort());
    });

    /**
     * The pair with byte-identical policies. Getting this wrong is the single
     * most likely way to ship a confidently incorrect security answer.
     */
    it("does not call a wildcard-policy bucket public when the access block neutralises it", () => {
      if (!available) return;
      for (const name of GROUND_TRUTH.blockedPublicBuckets) {
        const bucket = byName(name);
        expect(bucket, `${name} should have been collected`).toBeDefined();
        expect(bucket?.derived.isPublic, `${name} should not be public`).toBe(false);
        expect(bucket?.derived.publicReason).toMatch(/RestrictPublicBuckets|BlockPublicPolicy/);
      }
    });
  });

  describe("which roles have admin access", () => {
    it("finds every effectively-admin role", () => {
      if (!available) return;
      const found = namesWhere((r) => r.kind === "IamRole" && r.derived.isAdmin === true);
      expect(found).toEqual([...GROUND_TRUTH.adminRoles].sort());
    });

    it("finds admin granted inline under an innocuous name", () => {
      if (!available) return;
      for (const name of GROUND_TRUTH.inlineAdminRoles) {
        const role = byName(name);
        expect(role?.derived.isAdmin, `${name} should be admin`).toBe(true);
        expect(role?.derived.adminReason).toContain("inline");
      }
    });

    it("does not flag correctly scoped roles", () => {
      if (!available) return;
      expect(byName("LambdaExecRole")?.derived.isAdmin).toBe(false);
      expect(byName("ReadOnlyAuditRole")?.derived.isAdmin).toBe(false);
    });
  });

  describe("what can reach the production database", () => {
    const reach = () => relationships.filter((r) => r.type === "CAN_REACH");

    it("reaches the private database from the internet despite it not being public", () => {
      if (!available) return;
      const db = byName("northwind-prod-db");
      expect(db?.properties["publiclyAccessible"]).toBe(false);
      expect(db?.derived.isPublic, "should be reachable transitively").toBe(true);
    });

    it("finds both the bastion route and the web/app tier route", () => {
      if (!available) return;
      const db = byName("northwind-prod-db")!;
      const direct = reach()
        .filter((r) => r.to === db.arn)
        .map((r) => resources.find((x) => x.arn === r.from)?.name);
      expect(direct).toContain("prod-bastion");
      expect(direct).toContain("prod-app-1");
    });

    /** The inverse trap: flagged public, reachable by nobody. */
    it("does not report the isolated database as reachable", () => {
      if (!available) return;
      for (const name of GROUND_TRUTH.falsePositivePublicDb) {
        const db = byName(name);
        expect(db?.properties["publiclyAccessible"]).toBe(true);
        expect(db?.derived.isPublic, `${name} opens no ports, so nothing can reach it`).toBeFalsy();
        expect(reach().filter((r) => r.to === db?.arn)).toHaveLength(0);
      }
    });

    it("exposes only the hosts that are genuinely internet-facing", () => {
      if (!available) return;
      const direct = reach()
        .filter((r) => r.from === INTERNET_ARN)
        .map((r) => resources.find((x) => x.arn === r.to)?.name);
      expect([...new Set(direct)].sort()).toEqual(
        ["prod-bastion", "prod-web-1", "prod-web-2", "staging-rdp-host"].sort(),
      );
    });
  });

  describe("what is costing money but not being used", () => {
    it("finds exactly the idle resources, by structural signal", () => {
      if (!available) return;
      const found = namesWhere((r) => r.derived.isIdle === true);
      expect(found).toEqual([...GROUND_TRUTH.idleResources].sort());
    });

    it("attaches a cost estimate that scales with volume size", () => {
      if (!available) return;
      const small = byName("orphaned-vol-1")?.derived.estimatedMonthlyCostUsd ?? 0;
      const large = byName("legacy-orphaned-vol")?.derived.estimatedMonthlyCostUsd ?? 0;
      expect(large).toBeGreaterThan(small);
    });
  });

  describe("which instances are not in a private subnet", () => {
    it("classifies subnets by routing rather than by name", () => {
      if (!available) return;
      const publicSubnets = resources.filter(
        (r) => r.kind === "Subnet" && r.derived.isPublic === true,
      );
      expect(publicSubnets.length).toBeGreaterThan(0);
      for (const subnet of publicSubnets) {
        expect(subnet.derived.publicReason).toContain("internet gateway");
      }
    });
  });

  describe("every derived verdict carries its evidence", () => {
    it("explains itself wherever a flag is set", () => {
      if (!available) return;
      for (const r of resources) {
        if (r.derived.isPublic === true) expect(r.derived.publicReason, r.name).toBeTruthy();
        if (r.derived.isAdmin === true) expect(r.derived.adminReason, r.name).toBeTruthy();
        if (r.derived.isIdle === true) expect(r.derived.idleReason, r.name).toBeTruthy();
      }
    });
  });
});
